// This is just a test, and I haven't been working with GLSL (OpenGL Shading Language) for long.
// Based on the code "Minecraft Blocks" by Reinder Nijhoff (https://www.shadertoy.com/view/MdlGz4)
// Modified by melcom (www.melcom-music.de)

float hash(float n) {
    return fract(sin(n) * 43758.5453); // Generiert einen Pseudozufallswert basierend auf 'n' / Generates a pseudorandom value based on 'n'
}

// Anpassung der Farben basierend auf den angegebenen Hex-Farben / Adjusting colors based on specified hex colors
bool getMaterialColor(vec3 pos, out vec3 color) {
    vec3 uv = fract(pos); // Berechnet den fraktionalen Teil der Position / Computes the fractional part of the position
    float n = dot(uv, vec3(1.0, 2.0, 3.0)); // Punktprodukt für Zufallszahlengenerierung / Dot product for random number generation
    float h = hash(n);
    float br = 1.0 - h * 0.2; // Helligkeit für Chrome-Effekt / Brightness for chrome effect

    // Hex-Farben in RGB konvertiert / Hex colors converted to RGB
    vec3 color1 = vec3(1.0 / 255.0 * 1.0, 31.0 / 255.0, 39.0 / 255.0); // #011f27
    vec3 color2 = vec3(24.0 / 255.0, 54.0 / 255.0, 65.0 / 255.0); // #183641
    vec3 color3 = vec3(38.0 / 255.0, 85.0 / 255.0, 103.0 / 255.0); // #265567
    vec3 color4 = vec3(190.0 / 255.0, 220.0 / 255.0, 216.0 / 255.0); // #bedcd8

    // Farben für die Blöcke definieren / Defining colors for the blocks
    if (mod(floor(pos.x) + floor(pos.y) + floor(pos.z), 4.0) == 0.0) {
        color = color1 * br;
    } else if (mod(floor(pos.x) + floor(pos.y) + floor(pos.z), 4.0) == 1.0) {
        color = color2 * br;
    } else if (mod(floor(pos.x) + floor(pos.y) + floor(pos.z), 4.0) == 2.0) {
        color = color3 * br;
    } else {
        color = color4 * br;
    }

    // Reflexionseffekte hinzufügen / Adding reflection effects
    vec3 reflectDir = reflect(normalize(pos - vec3(32.5)), normalize(vec3(0.0, 1.0, 0.0)));
    color += pow(max(dot(reflectDir, vec3(0.0, 1.0, 0.0)), 0.0), 2.0) * vec3(1.0);

    return true;
}

// Berechnet den Map-Wert basierend auf der Position / Computes the map value based on position
int getMap(vec3 pos) {
    vec3 posf = floor((pos - vec3(32.0))); // Abrunden der Position / Flooring the position
    float n = posf.x + posf.y * 517.0 + 1313.0 * posf.z; // Berechnet einen einzigartigen Wert für die Position / Computes a unique value for the position
    float h = hash(n);

    if (h > sqrt(sqrt(dot(posf.yz, posf.yz) * 0.16)) - 0.8) {
        return 0;
    }

    return int(hash(n * 465.233) * 16.0); // Gibt einen Integer-Wert basierend auf der Hash-Funktion zurück / Returns an integer value based on the hash function
}

// Rendert Chrome-Blöcke basierend auf den UV-Koordinaten / Renders chrome blocks based on UV coordinates
vec3 renderChromeBlocks(vec2 uv) {
    float xRot = sin(iTime * 0.5) * 0.4 + (3.1415 / 2.0); // Berechnet die X-Rotation / Computes the X rotation
    float yRot = cos(iTime * 0.5) * 0.4; // Berechnet die Y-Rotation / Computes the Y rotation
    float yCos = cos(yRot);
    float ySin = sin(yRot);
    float xCos = cos(xRot);
    float xSin = sin(xRot);

    // Ausgangsposition und Richtung der Strahlenberechnung / Initial position and ray direction calculation
    vec3 opos = vec3(32.5 + iTime * 6.4, 32.5, 32.5);
    float gggxd = (uv.x - 0.5) * (iResolution.x / iResolution.y);
    float ggyd = (1.0 - uv.y - 0.5);
    float ggzd = 1.0;
    float gggzd = ggzd * yCos + ggyd * ySin;
    vec3 _posd = vec3(gggxd * xCos + gggzd * xSin, ggyd * yCos - ggzd * ySin, gggzd * xCos - gggxd * xSin);
    vec3 col = vec3(0.0);
    float br = 1.0;
    vec3 bdist = vec3(255.0 - 100.0, 255.0 - 0.0, 255.0 - 50.0);
    float ddist = 0.0;
    float closest = 32.0;

    // Berechnet die nächsten Blöcke entlang der Strahlenrichtung / Computes the nearest blocks along the ray direction
    for (int d = 0; d < 3; d++) {
        float dimLength = _posd[d];
        float ll = abs(1.0 / dimLength);
        vec3 posd = _posd * ll;
        float initial = fract(opos[d]);
        if (dimLength > 0.0) initial = 1.0 - initial;
        float dist = ll * initial;
        vec3 pos = opos + posd * initial;
        if (dimLength < 0.0) pos[d] -= 1.0;

        // Überprüfen und Rendern der Blöcke / Checking and rendering the blocks
        for (int i = 0; i < 30; i++) {
            if (dist > closest) continue;
            int tex = getMap(pos);
            if (tex > 0) {
                vec3 texColor;
                if (getMaterialColor(pos, texColor)) {
                    ddist = 1.0 - (dist / 32.0);
                    br = bdist[d];
                    col = texColor;
                    closest = dist;
                }
            }
            pos += posd;
            dist += ll;
        }
    }

    return col * ddist * (br / 255.0); // Rückgabe der finalen Farbwerte / Returning the final color values
}

// Haupteingabefunktion / Main input function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy; // Normierung der Fragmentkoordinaten / Normalizing the fragment coordinates
    fragColor = vec4(renderChromeBlocks(uv), 1.0); // Setzt die Fragmentfarbe basierend auf den berechneten Farbwerten / Sets the fragment color based on the calculated color values
}
